insert into public.qualifications(id,title,description,published,college_id,qualification_code,qualification_level,academic_year,official_url)
select gen_random_uuid(),'Bachelor of Commerce Honours in Business Informatics','UNISA qualification code 98450. Curriculum comprises two compulsory modules, two choices from the information systems group and two choices from the business/elective group.',true,'CEMS','98450','Honours degree',2026,'https://m.unisa.ac.za/sites/corporate/default/Register-to-study-through-Unisa/Undergraduate-%26-honours-qualifications/Find-your-qualification-%26-choose-your-modules/All-qualifications/Bachelor-of-Commerce-Honours-in-Business-Informatics-%2898450%29'
where not exists(select 1 from public.qualifications where qualification_code='98450' and college_id='CEMS');
